/* -------------------------------------------------------------------------
   Button

   Sizing: explicit height + padding per size (shadcn/Radix convention).
   Gap, radius, icon-size remain em-relative for proportional scaling.

   Variants: primary, secondary, tertiary,
             destructive, destructive-secondary, destructive-tertiary
   Sizes:    xs, s, m (default), l, xl
   States:   enabled, hover, focus, active, disabled, loading
   ------------------------------------------------------------------------- */

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5em;
  border-radius: 0.625em;
  border: 1px solid transparent;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-weight: 500;
  line-height: 1;
  width: auto;
  max-width: 100%;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-decoration: none;
  box-shadow: 0 0 #0000;
  transition:
    background-color 300ms cubic-bezier(0.22, 1, 0.36, 1),
    color 300ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 300ms cubic-bezier(0.22, 1, 0.36, 1),
    scale 500ms cubic-bezier(0.32, 0.72, 0, 1);
  position: relative;
}

.button:active:not(.button--disabled):not(.button--loading) {
  scale: 0.955 0.925;
}

.button:focus-visible {
  outline: 2px solid #0a0a0a;
  outline-offset: 1.5px;
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .button[data-button-animate]:hover:not(.button--disabled):not(.button--loading) {
    scale: 1.06 1.095;
  }
}

@media (prefers-reduced-motion: reduce) {
  .button {
    transition-duration: 0ms;
  }
  .button:active:not(.button--disabled) {
    scale: 1;
  }
}

/* ---- Sizes (same font-size, different height + padding) ---- */

.button--xs {
  height: 28px;
  padding: 0 8px;
  font-size: 12.8px;
}

.button--s {
  height: 32px;
  padding: 0 12px;
  font-size: 12.8px;
}

.button--m {
  height: 40px;
  padding: 0 16px;
  font-size: 12.8px;
}

.button--l {
  height: 48px;
  padding: 0 24px;
  font-size: 12.8px;
}

.button--xl {
  height: 52px;
  padding: 0 32px;
  font-size: 12.8px;
}

/* ---- Variants ---- */

.button--primary {
  background-color: #0a0a0a;
  color: #fafafa;
}
.button--primary:hover:not(.button--disabled) {
  background-color: #262626;
}
.button--primary:active:not(.button--disabled) {
  background-color: #f5f5f5;
}

.button--secondary {
  background-color: #fafafa;
  color: #0a0a0a;
  border-color: #e5e5e5;
}
.button--secondary:hover:not(.button--disabled) {
  background-color: #f5f5f5;
}
.button--secondary:active:not(.button--disabled) {
  background-color: #f5f5f5;
}

.button--tertiary {
  background-color: #00000000;
  color: #0a0a0a;
}
.button--tertiary:hover:not(.button--disabled) {
  background-color: #f5f5f5;
}
.button--tertiary:active:not(.button--disabled) {
  background-color: #f5f5f5;
}

.button--destructive-primary {
  background-color: #f84131;
  color: #0a0a0a;
}
.button--destructive-primary:hover:not(.button--disabled) {
  background-color: #c21e12;
}
.button--destructive-primary:active:not(.button--disabled) {
  background-color: #c21e12;
}

.button--destructive-secondary {
  background-color: #fafafa;
  color: #f84131;
  border-color: #f84131;
}
.button--destructive-secondary:hover:not(.button--disabled) {
  background-color: #f5f5f5;
}
.button--destructive-secondary:active:not(.button--disabled) {
  background-color: #f5f5f5;
}

.button--destructive-tertiary {
  background-color: #00000000;
  color: #f84131;
}
.button--destructive-tertiary:hover:not(.button--disabled) {
  background-color: #f5f5f5;
}
.button--destructive-tertiary:active:not(.button--disabled) {
  background-color: #f5f5f5;
}

/* ---- States ---- */

.button--disabled {
  color: #525252;
  cursor: not-allowed;
  pointer-events: none;
}

.button--disabled.button--primary,
.button--disabled.button--secondary,
.button--disabled.button--destructive-primary,
.button--disabled.button--destructive-secondary {
  background-color: #f5f5f5;
  border-color: transparent;
}

.button--disabled.button--tertiary,
.button--disabled.button--destructive-tertiary {
  background-color: transparent;
  border-color: transparent;
}

.button--loading {
  cursor: wait;
  pointer-events: none;
}

.button--loading .button__label {
  opacity: 0;
}

.button--loading .button__spinner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ---- Parts ---- */

.button__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
}

.button__icon svg {
  width: 100%;
  height: 100%;
}

.button__label {
  display: inline-flex;
  align-items: center;
}


.button__spinner {
  display: none;
}

.button--loading .button__spinner {
  display: flex;
}

.button__spinner-icon {
  animation: button-spin 700ms linear infinite;
}

@keyframes button-spin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .button__spinner-icon {
    animation: none;
  }
}

/* -------------------------------------------------------------------------
   Icon Button

   Square button with icon only, no label.
   Shares color variants with Button. Own sizing and animation.

   Variants: primary, secondary, tertiary,
             destructive, destructive-secondary, destructive-tertiary
   Sizes:    xs, sm, default (default), lg, xl
   Animation: icon 360deg rotation on hover (opt-in via data-icon-button-animate)
   ------------------------------------------------------------------------- */

.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 1;
  padding: 0;
  border-radius: 0.625em;
  border: 1px solid transparent;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-decoration: none;
  transition:
    background-color 0.3s cubic-bezier(0.19, 1, 0.22, 1),
    color 0.3s cubic-bezier(0.19, 1, 0.22, 1),
    border-color 0.3s cubic-bezier(0.19, 1, 0.22, 1),
    scale 0.45s cubic-bezier(0.32, 0.72, 0, 1);
  position: relative;
}

.icon-button:active:not(.icon-button--disabled):not(.icon-button--loading) {
  scale: 0.925;
}

.icon-button:focus-visible {
  outline: 2px solid #0a0a0a;
  outline-offset: 1.5px;
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .icon-button[data-icon-button-animate]:hover:not(.icon-button--disabled):not(.icon-button--loading) {
    scale: 1.095;
  }
}

@media (prefers-reduced-motion: reduce) {
  .icon-button {
    transition-duration: 0ms;
  }
  .icon-button:active:not(.icon-button--disabled) {
    scale: 1;
  }
}

/* ---- Sizes (square: width = height) ---- */

.icon-button--xs      { width: 28px; height: 28px; font-size: 12.8px; }
.icon-button--s      { width: 32px; height: 32px; font-size: 12.8px; }
.icon-button--m { width: 40px; height: 40px; font-size: 12.8px; }
.icon-button--l      { width: 48px; height: 48px; font-size: 12.8px; }
.icon-button--xl      { width: 52px; height: 52px; font-size: 12.8px; }

/* ---- Variants (same tokens as Button) ---- */

.icon-button--primary {
  background-color: #0a0a0a;
  color: #fafafa;
}
.icon-button--primary:hover:not(.icon-button--disabled) {
  background-color: #262626;
}
.icon-button--primary:active:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}

.icon-button--secondary {
  background-color: #fafafa;
  color: #0a0a0a;
  border-color: #e5e5e5;
}
.icon-button--secondary:hover:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}
.icon-button--secondary:active:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}

.icon-button--tertiary {
  background-color: #00000000;
  color: #0a0a0a;
}
.icon-button--tertiary:hover:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}
.icon-button--tertiary:active:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}

.icon-button--destructive-primary {
  background-color: #f84131;
  color: #0a0a0a;
}
.icon-button--destructive-primary:hover:not(.icon-button--disabled) {
  background-color: #c21e12;
}
.icon-button--destructive-primary:active:not(.icon-button--disabled) {
  background-color: #c21e12;
}

.icon-button--destructive-secondary {
  background-color: #fafafa;
  color: #f84131;
  border-color: #f84131;
}
.icon-button--destructive-secondary:hover:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}
.icon-button--destructive-secondary:active:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}

.icon-button--destructive-tertiary {
  background-color: #00000000;
  color: #f84131;
}
.icon-button--destructive-tertiary:hover:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}
.icon-button--destructive-tertiary:active:not(.icon-button--disabled) {
  background-color: #f5f5f5;
}

/* ---- States ---- */

.icon-button--disabled {
  color: #525252;
  cursor: not-allowed;
  pointer-events: none;
}

.icon-button--disabled.icon-button--primary,
.icon-button--disabled.icon-button--secondary,
.icon-button--disabled.icon-button--destructive-primary,
.icon-button--disabled.icon-button--destructive-secondary {
  background-color: #f5f5f5;
  border-color: transparent;
}

.icon-button--disabled.icon-button--tertiary,
.icon-button--disabled.icon-button--destructive-tertiary {
  background-color: transparent;
  border-color: transparent;
}

.icon-button--loading {
  cursor: wait;
  pointer-events: none;
}

/* ---- Icon ---- */

.icon-button__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.25em;
  height: 1.25em;
  will-change: transform;
  transition: rotate 0.5s cubic-bezier(0.19, 1, 0.22, 1);
}

.icon-button__icon svg {
  width: 100%;
  height: 100%;
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .icon-button[data-icon-button-animate]:is(:hover, :focus-visible) .icon-button__icon,
  [data-hover]:is(:hover, :focus-visible) .icon-button[data-icon-button-animate] .icon-button__icon {
    rotate: 360deg;
    transition: rotate 0.6s 0.05s cubic-bezier(0.19, 1, 0.22, 1);
  }
}

/* ---- Spinner ---- */

.icon-button__spinner {
  display: none;
}

.icon-button--loading .icon-button__icon {
  opacity: 0;
}

.icon-button--loading .icon-button__spinner {
  display: flex;
  position: absolute;
  inset: 0;
  align-items: center;
  justify-content: center;
}

/* -------------------------------------------------------------------------
   Link Button

   Semantic link (<a>) for external navigation. Not a button.
   Blue text with animated underline on hover. No background, no border.

   Sizes:    xs, sm, default, lg, xl
   States:   enabled, hover, focus, disabled
   ------------------------------------------------------------------------- */

.link-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  padding: 0;
  background: none;
  border: none;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-weight: 500;
  line-height: 1;
  color: #0e7490;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-decoration: none;
  transition: color 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.link-button:hover:not(.link-button--disabled) {
  color: #0a0a0a;
}

.link-button:active:not(.link-button--disabled) {
  color: #0a0a0a;
}

.link-button:focus-visible {
  outline: 2px solid #0a0a0a;
  outline-offset: 1.5px;
  border-radius: 0.125em;
}

@media (prefers-reduced-motion: reduce) {
  .link-button {
    transition-duration: 0ms;
  }
}

/* ---- Sizes ---- */

.link-button--xs      { font-size: 10.24px; }
.link-button--sm      { font-size: 12.8px; }
.link-button--default { font-size: 16px; }
.link-button--lg      { font-size: 20px; }
.link-button--xl      { font-size: 25px; }

/* ---- States ---- */

.link-button--disabled {
  color: #525252;
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Parts ---- */

.link-button__text {
  display: inline;
  position: relative;
}

/* ---- Underline animation ---- */

.link-button__text::before {
  content: "";
  position: absolute;
  bottom: -0.0625em;
  left: 0;
  width: 100%;
  height: 0.0625em;
  background-color: currentColor;
  transition: transform 0.735s cubic-bezier(0.625, 0.05, 0, 1);
  transform-origin: right;
  transform: scaleX(0) rotate(0.001deg);
}

@media (hover: hover) and (pointer: fine) {
  .link-button--animated:hover:not(.link-button--disabled) .link-button__text::before,
  [data-hover]:hover .link-button--animated:not(.link-button--disabled) .link-button__text::before {
    transform-origin: left;
    transform: scaleX(1) rotate(0.001deg);
  }
}

/* ---- Animated variant: persistent underline + text shimmer ---- */

.link-button--animated:not(.link-button--disabled) .link-button__text::before {
  transform-origin: left;
  transform: scaleX(1) rotate(0.001deg);
}

.link-button--animated:not(.link-button--disabled) .link-button__text {
  background: linear-gradient(
    120deg,
    currentColor 0%,
    currentColor 35%,
    color-mix(in srgb, currentColor 40%, white) 50%,
    currentColor 65%,
    currentColor 100%
  );
  background-size: 200% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: link-button-shimmer 3s ease-in-out infinite;
}

@keyframes link-button-shimmer {
  0%, 100% { background-position: 200% center; }
  50% { background-position: 0% center; }
}

@media (prefers-reduced-motion: reduce) {
  .link-button--animated:not(.link-button--disabled) .link-button__text {
    animation: none;
    background: none;
    -webkit-text-fill-color: currentColor;
  }
}

