/* -------------------------------------------------------------------------
   Field

   Wrapper for form controls: label + input + description + error.
   Composes with Input, Textarea, Select, Checkbox, etc.
   Colors matched to Figma atom-text-field.

   Orientation: vertical (default)
   ------------------------------------------------------------------------- */

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
}

.field__label {
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 10.24px;
  font-weight: 500;
  line-height: 1;
  color: #0a0a0a;
}

.field__label--required::after {
  content: " *";
  color: #f84131;
}

.field__description {
  margin-top: 4px;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 10.24px;
  line-height: 1.4;
  color: #525252;
}

.field__error {
  margin-top: 4px;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 10.24px;
  line-height: 1.4;
  color: #f84131;
}

/* Error state — label turns red */
.field[data-invalid] .field__label {
  color: #f84131;
}

/* Disabled state — label grays out */
.field--disabled .field__label {
  color: #525252;
}

/* -------------------------------------------------------------------------
   Tabs

   Tabbed content switcher. Horizontal or vertical.
   Variants: default (pill bg), line (underline indicator).

   Parts: .tabs, .tabs__list, .tabs__trigger, .tabs__content
   ------------------------------------------------------------------------- */

/* ---- Root ---- */

.tabs {
  display: flex;
  flex-direction: column;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
}

.tabs--vertical {
  flex-direction: row;
  gap: 16px;
}

/* ---- List ---- */

.tabs__list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;
  padding: 3px;
  background-color: #f5f5f5;
  border-radius: 12px;
}

.tabs__list .tabs__trigger {
  flex: 1;
  text-align: center;
}

/* Line variant: no bg, bottom border */
.tabs__list--line {
  background: none;
  border-radius: 0;
  padding: 0;
  gap: 0;
  border-bottom: 1px solid #e5e5e5;
}

/* Vertical list */
.tabs--vertical .tabs__list {
  flex-direction: column;
  align-items: stretch;
}

.tabs--vertical .tabs__list:not(.tabs__list--line) {
  border-radius: 12px;
}

.tabs--vertical .tabs__list--line {
  border-bottom: none;
  border-right: 1px solid #e5e5e5;
}

/* ---- Animated indicator ---- */

.tabs__list--animated {
  position: relative;
}

.tabs__indicator {
  position: absolute;
  border-radius: 8px;
  background-color: #fafafa;
  box-shadow: 0 1px rgb(0 0 0 / 0.05);
  pointer-events: none;
  z-index: 0;
  transition:
    left 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    top 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    width 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    height 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    opacity 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

.tabs__list--animated .tabs__trigger {
  position: relative;
  z-index: 1;
}

.tabs__list--animated .tabs__trigger--active {
  background: none;
  box-shadow: none;
}

/* ---- Trigger ---- */

.tabs__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 12px;
  border: none;
  border-radius: 8px;
  background: none;
  color: color-mix(in srgb, #0a0a0a 55%, #525252);
  font-family: inherit;
  font-size: 12.8px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    color 150ms cubic-bezier(0.4, 0, 0.2, 1),
    background-color 150ms cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.tabs__trigger:hover {
  color: #0a0a0a;
}

.tabs__trigger:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: -2px;
}

/* Active (default variant) */
.tabs__trigger--active {
  background-color: #fafafa;
  color: #0a0a0a;
  box-shadow: 0 1px rgb(0 0 0 / 0.05);
}

/* Disabled */
.tabs__trigger--disabled {
  color: #525252;
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Line variant triggers ---- */

.tabs__list--line .tabs__trigger {
  border-radius: 0;
  padding: 8px 16px;
  position: relative;
}

.tabs__list--line .tabs__trigger::after {
  content: "";
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background-color: transparent;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.tabs__list--line .tabs__trigger--active {
  background: none;
  box-shadow: none;
  color: #0a0a0a;
}

.tabs__list--line .tabs__trigger--active::after {
  background-color: #0a0a0a;
}

/* Line vertical */
.tabs--vertical .tabs__list--line .tabs__trigger::after {
  bottom: auto;
  left: auto;
  right: -1px;
  top: 0;
  width: 2px;
  height: 100%;
}

/* ---- Trigger icon ---- */

.tabs__trigger-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1em;
  height: 1em;
}

.tabs__trigger-icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Content ---- */

.tabs__content {
  padding-top: 16px;
}

.tabs--vertical .tabs__content {
  padding-top: 0;
  flex: 1;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .tabs__trigger,
  .tabs__list--line .tabs__trigger::after {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Divider

   Horizontal or vertical separator line.
   Figma: atom-horizontal-divider. We add vertical variant.

   Orientation: horizontal (default), vertical
   ------------------------------------------------------------------------- */

.divider {
  border: none;
  margin: 0;
  flex-shrink: 0;
}

.divider--horizontal {
  width: 100%;
  height: 0;
  border-top: 1px solid #e5e5e5;
}

.divider--vertical {
  height: 100%;
  width: 0;
  border-left: 1px solid #e5e5e5;
  align-self: stretch;
}

/* ---- Labeled: etiqueta + linea que ocupa el resto (patron de seccion) ---- */

.divider--labeled {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  height: auto;
  border: none;
  color: #525252;
}

.divider--labeled::after {
  flex: 1;
  height: 1px;
  content: '';
  background-color: currentcolor;
  opacity: 0.15;
}

/* -------------------------------------------------------------------------
   Avatar

   User representation: image, initials, or icon placeholder.
   Optional status dot (online indicator).

   Types:   image, image-border, initials, icon
   Shapes:  circle, square
   Sizes:   xs (24px), s (32px), m (40px), l (48px)
   ------------------------------------------------------------------------- */

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
  background-color: #f5f5f5;
}

.avatar__image {
  overflow: hidden;
}

/* ---- Sizes ---- */

.avatar--xs { width: 1.5rem; height: 1.5rem; }
.avatar--s  { width: 2rem; height: 2rem; }
.avatar--m  { width: 2.5rem; height: 2.5rem; }
.avatar--l  { width: 3rem; height: 3rem; }

/* ---- Shapes ---- */

.avatar--circle { border-radius: 9999px; }

.avatar--square.avatar--xs { border-radius: 8px; }
.avatar--square.avatar--s  { border-radius: 8px; }
.avatar--square.avatar--m  { border-radius: 12px; }
.avatar--square.avatar--l  { border-radius: 16px; }

/* ---- Types ---- */

/* Image (no border) */
.avatar--image {
  background: none;
  padding: 0;
}

/* Image with border ring */
.avatar--image-border {
  padding: 0.125rem;
}
.avatar--image-border.avatar--m,
.avatar--image-border.avatar--l {
  padding: 0.25rem;
}

/* Initials */
.avatar--initials {
  border: 2px solid #e5e5e5;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-weight: 400;
  color: #171717;
  font-size: 12.8px;
  line-height: 1;
}
.avatar--initials.avatar--l {
  font-size: 16px;
}

/* Icon */
.avatar--icon {
  border: 2px solid #e5e5e5;
  color: #525252;
}

/* ---- Image element ---- */

.avatar__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: inherit;
}

.avatar--circle .avatar__image {
  border-radius: 9999px;
}

/* ---- Icon element ---- */

.avatar__icon {
  display: flex;
  align-items: center;
  justify-content: center;
}

.avatar--xs .avatar__icon { width: 0.75rem; height: 0.75rem; }
.avatar--s .avatar__icon  { width: 1rem; height: 1rem; }
.avatar--m .avatar__icon  { width: 1.25rem; height: 1.25rem; }
.avatar--l .avatar__icon  { width: 1.5rem; height: 1.5rem; }

.avatar__icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Status dot ---- */

.avatar__status {
  position: absolute;
  background-color: #25d366;
  border-radius: 9999px;
  border-style: solid;
  border-color: #fafafa;
}

.avatar--xs .avatar__status { width: 0.5rem; height: 0.5rem; border-width: 1px; bottom: -0.0625rem; right: -0.0625rem; }
.avatar--s .avatar__status  { width: 0.5rem; height: 0.5rem; border-width: 1px; bottom: 0; right: 0; }
.avatar--m .avatar__status  { width: 0.75rem; height: 0.75rem; border-width: 1.5px; bottom: 0; right: 0; }
.avatar--l .avatar__status  { width: 1rem; height: 1rem; border-width: 2px; bottom: 0; right: 0; }

/* ---- Skeleton ---- */

.avatar--skeleton {
  border: none;
  animation: avatar-skeleton-pulse 1.5s ease-in-out infinite;
}

.avatar--skeleton * {
  display: none;
}

@keyframes avatar-skeleton-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

/* -------------------------------------------------------------------------
   Badge

   Numeric counter pill. Compact indicator for counts and notifications.
   Non-interactive. Fixed height (16px), pill shape, truncates with ellipsis.

   Variants: neutral, inbox
   States:   enabled, focused, subtle
   ------------------------------------------------------------------------- */

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1rem;
  max-width: 2.25rem;
  height: 1rem;
  padding: 0 4px;
  border-radius: 9999px;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif;
  font-size: 10.24px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
}

.badge__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: center;
  min-width: 1px;
}

/* ---- Neutral ---- */

.badge--neutral.badge--enabled {
  background-color: #f5f5f5;
  color: #0a0a0a;
}

.badge--neutral.badge--focused {
  background-color: #0a0a0a;
  color: #fafafa;
}

.badge--neutral.badge--subtle {
  background-color: #262626;
  color: #fafafa;
}

/* ---- Inbox ---- */

.badge--inbox.badge--enabled {
  background-color: #fb7a6e;
  color: #0a0a0a;
}

.badge--inbox.badge--focused {
  background-color: #c21e12;
  color: #fafafa;
}

.badge--inbox.badge--subtle {
  background-color: #f84131;
  color: #0a0a0a;
}

/* -------------------------------------------------------------------------
   Spinner

   Loading indicator. Rotating circle with partial stroke.
   Sizes: xs, s, m, l. Inherits color from parent.

   Parts: .spinner
   ------------------------------------------------------------------------- */

.spinner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: currentColor;
  animation: spinner-rotate 700ms linear infinite;
}

/* ---- Sizes ---- */

.spinner--xs { width: 0.875rem; height: 0.875rem; }
.spinner--s  { width: 1.125rem; height: 1.125rem; }
.spinner--m  { width: 1.5rem; height: 1.5rem; }
.spinner--l  { width: 2rem; height: 2rem; }

.spinner svg {
  width: 100%;
  height: 100%;
}

@keyframes spinner-rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Skeleton

   Loading placeholder. Pulse animation on muted background.
   Consumer sets width/height/border-radius via style or className.

   Parts: .skeleton
   ------------------------------------------------------------------------- */

.skeleton {
  display: block;
  background-color: #e5e5e5;
  border-radius: 8px;
  animation: skeleton-pulse 1000ms cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

@keyframes skeleton-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

/* ---- Shape helpers ---- */

.skeleton--circle {
  border-radius: 9999px;
}

.skeleton--text {
  height: 1em;
  border-radius: 4px;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .skeleton {
    animation: none;
  }
}

/* -------------------------------------------------------------------------
   Dialog

   Modal window with overlay. Focus-trapped, scroll-locked.
   Composable: Dialog > Trigger + Content > Header + Footer

   Parts: .dialog__overlay, .dialog__content, .dialog__header,
          .dialog__title, .dialog__description, .dialog__footer,
          .dialog__close
   ------------------------------------------------------------------------- */

/* ---- Overlay ---- */

.dialog__overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  background-color: #00000080;
  animation: dialog-overlay-in 200ms cubic-bezier(0.22, 1, 0.36, 1);
}

.dialog__overlay--exiting {
  animation: dialog-overlay-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

@keyframes dialog-overlay-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes dialog-overlay-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

/* ---- Content ---- */

.dialog__content {
  position: fixed;
  z-index: 50;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: calc(100% - 32px);
  max-width: 512px;
  max-height: calc(100vh - 32px);
  display: flex;
  flex-direction: column;
  border: 1px solid #e5e5e5;
  border-radius: 16px;
  background-color: #ffffff;
  color: #0a0a0a;
  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  animation: dialog-content-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}

.dialog__content--exiting {
  animation: dialog-content-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

@keyframes dialog-content-in {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

@keyframes dialog-content-out {
  from {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
}

/* ---- Header ---- */

.dialog__header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 24px;
  padding-bottom: 0;
}

/* ---- Title ---- */

.dialog__title {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.45;
  color: #0a0a0a;
  margin: 0;
}

/* ---- Description ---- */

.dialog__description {
  font-size: 12.8px;
  line-height: 1.45;
  color: #525252;
  margin: 0;
}

/* ---- Body (scrollable) ---- */

.dialog__body {
  flex: 1;
  overflow-y: auto;
  padding: 24px;
}

/* ---- Footer ---- */

.dialog__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding: 24px;
  padding-top: 0;
}

.dialog__footer--sticky {
  border-top: 1px solid #e5e5e5;
  padding-top: 24px;
}

/* ---- Close button ---- */

.dialog__close {
  position: absolute;
  top: 16px;
  right: 16px;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .dialog__overlay,
  .dialog__overlay--exiting,
  .dialog__content,
  .dialog__content--exiting {
    animation-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Table

   Semantic HTML table with consistent styling.
   Thin wrapper: Table, TableHeader, TableBody, TableFooter,
                 TableRow, TableHead, TableCell, TableCaption

   Parts: .table, .table__header, .table__body, .table__footer,
          .table__row, .table__head, .table__cell, .table__caption
   ------------------------------------------------------------------------- */

/* ---- Wrapper ---- */

.table-wrapper {
  width: 100%;
  overflow-x: auto;
}

/* ---- Table ---- */

.table {
  width: 100%;
  border-collapse: collapse;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 12.8px;
  line-height: 1.45;
  text-align: left;
}

/* ---- Caption ---- */

.table__caption {
  padding-top: 16px;
  font-size: 12.8px;
  color: #525252;
  caption-side: bottom;
}

/* ---- Header ---- */

.table__header {
  border-bottom: 1px solid #e5e5e5;
}

.table__head {
  padding: 12px 16px;
  font-weight: 500;
  color: #525252;
  white-space: nowrap;
  vertical-align: middle;
  height: 40px;
}

/* ---- Body ---- */

.table__row {
  border-bottom: 1px solid #e5e5e5;
  transition: background-color 100ms cubic-bezier(0.4, 0, 0.2, 1);
}

.table__row:hover {
  background-color: #f5f5f5;
}

.table__row--selected {
  background-color: #f5f5f5;
}

.table__cell {
  padding: 12px 16px;
  color: #0a0a0a;
  vertical-align: middle;
}

/* ---- Footer ---- */

.table__footer {
  border-top: 1px solid #e5e5e5;
  background-color: #f5f5f5;
}

.table__footer .table__cell {
  font-weight: 600;
}

/* ---- Alignment helpers ---- */

.table__head--right,
.table__cell--right {
  text-align: right;
}

.table__head--center,
.table__cell--center {
  text-align: center;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .table__row {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Accordion

   Collapsible content sections. Single or multiple open.
   All colors via semantic tokens. Spacing via token values.

   Parts: .accordion, .accordion__item, .accordion__trigger, .accordion__content
   ------------------------------------------------------------------------- */

.accordion {
  width: 100%;
}

.accordion__item {
  border-bottom: 1px solid #e5e5e5;
}

.accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 16px 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.4;
  color: #0a0a0a;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  transition: color 0.15s ease;
}

.accordion__trigger:hover {
  color: #525252;
}

.accordion__trigger:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: 2px;
  border-radius: 4px;
}

.accordion__chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  color: #525252;
  transition: transform 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.accordion__chevron svg {
  width: 100%;
  height: 100%;
}

.accordion__item--open .accordion__chevron {
  transform: rotate(180deg);
}

/* Content: animated height via grid */
.accordion__content-wrapper {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.accordion__item--open .accordion__content-wrapper {
  grid-template-rows: 1fr;
}

.accordion__content {
  overflow: hidden;
  min-height: 0;
}

.accordion__content-inner {
  padding-bottom: 16px;
  font-family: inherit;
  font-size: 12.8px;
  line-height: 1.45;
  color: #525252;
}

@media (prefers-reduced-motion: reduce) {
  .accordion__content-wrapper,
  .accordion__chevron {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Alert Dialog

   Non-dismissible confirmation modal. No overlay close, no X button.
   Requires explicit Cancel or Action to close.

   Sizes: default (512px), sm (400px)
   Parts: .alert-dialog, .alert-dialog__header, .alert-dialog__media,
          .alert-dialog__title, .alert-dialog__description,
          .alert-dialog__footer
   ------------------------------------------------------------------------- */

/* ---- Content ---- */

.alert-dialog {
  position: fixed;
  z-index: 50;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: calc(100% - 32px);
  max-width: 512px;
  display: flex;
  flex-direction: column;
  border: 1px solid #e5e5e5;
  border-radius: 16px;
  background-color: #ffffff;
  color: #0a0a0a;
  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  animation: alert-dialog-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}

.alert-dialog--sm {
  max-width: 400px;
}

.alert-dialog--exiting {
  animation: alert-dialog-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

@keyframes alert-dialog-in {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

@keyframes alert-dialog-out {
  from {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
}

/* ---- Header ---- */

.alert-dialog__header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 24px;
  padding-bottom: 0;
  text-align: center;
}

/* ---- Media ---- */

.alert-dialog__media {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 9999px;
  background-color: #f5f5f5;
  color: #525252;
  padding: 12px;
}

.alert-dialog__media--destructive {
  background-color: #f84131;
  color: #0a0a0a;
}

.alert-dialog__media svg {
  width: 100%;
  height: 100%;
}

/* ---- Title ---- */

.alert-dialog__title {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.45;
  color: #0a0a0a;
  margin: 0;
}

/* ---- Description ---- */

.alert-dialog__description {
  font-size: 12.8px;
  line-height: 1.45;
  color: #525252;
  margin: 0;
}

/* ---- Footer ---- */

.alert-dialog__footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 24px;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .alert-dialog,
  .alert-dialog--exiting {
    animation-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Avatar Group

   Stacked row of avatars with negative overlap.
   Wraps standard Avatar components.

   Sizes:   xs, s, m, l (match Avatar sizes)
   Parts:   .avatar-group, .avatar-group__count
   ------------------------------------------------------------------------- */

.avatar-group {
  display: inline-flex;
  align-items: center;
}

/* Negative overlap per size */

.avatar-group--xs > .avatar { margin-left: -0.375rem; }
.avatar-group--s  > .avatar { margin-left: -0.5rem; }
.avatar-group--m  > .avatar { margin-left: -0.625rem; }
.avatar-group--l  > .avatar { margin-left: -0.75rem; }

.avatar-group > .avatar:first-child { margin-left: 0; }

/* Z-index: first child on top, descending */

.avatar-group > .avatar,
.avatar-group > .avatar-group__count {
  position: relative;
}

.avatar-group > :nth-child(1)  { z-index: 10; }
.avatar-group > :nth-child(2)  { z-index: 9; }
.avatar-group > :nth-child(3)  { z-index: 8; }
.avatar-group > :nth-child(4)  { z-index: 7; }
.avatar-group > :nth-child(5)  { z-index: 6; }
.avatar-group > :nth-child(6)  { z-index: 5; }
.avatar-group > :nth-child(7)  { z-index: 4; }
.avatar-group > :nth-child(8)  { z-index: 3; }
.avatar-group > :nth-child(9)  { z-index: 2; }
.avatar-group > :nth-child(10) { z-index: 1; }

/* Ring to separate overlapping avatars */

.avatar-group > .avatar {
  box-shadow: 0 0 0 2px #fafafa;
}

/* Count badge (+3 more) */

.avatar-group__count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  background-color: #f5f5f5;
  color: #525252;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-weight: 500;
  line-height: 1;
  box-shadow: 0 0 0 2px #fafafa;
}

/* Count badge inherits square shape */
.avatar-group--square .avatar-group__count { border-radius: 8px; }
.avatar-group--square.avatar-group--m .avatar-group__count { border-radius: 12px; }
.avatar-group--square.avatar-group--l .avatar-group__count { border-radius: 16px; }

.avatar-group--xs .avatar-group__count { width: 1.5rem; height: 1.5rem; font-size: 10.24px; margin-left: -0.375rem; }
.avatar-group--s  .avatar-group__count { width: 2rem; height: 2rem; font-size: 10.24px; margin-left: -0.5rem; }
.avatar-group--m  .avatar-group__count { width: 2.5rem; height: 2.5rem; font-size: 12.8px; margin-left: -0.625rem; }
.avatar-group--l  .avatar-group__count { width: 3rem; height: 3rem; font-size: 12.8px; margin-left: -0.75rem; }

