/* -------------------------------------------------------------------------
   Breadcrumb

   Navigation trail showing current location in hierarchy.
   All semantic tokens. Inherits font from parent.

   Parts: .breadcrumb, .breadcrumb__list, .breadcrumb__item,
          .breadcrumb__link, .breadcrumb__page, .breadcrumb__separator
   ------------------------------------------------------------------------- */

.breadcrumb {
  font-family: inherit;
  font-size: 12.8px;
  line-height: 1;
}

.breadcrumb__list {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  list-style: none;
  margin: 0;
  padding: 0;
}

.breadcrumb__item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.breadcrumb__link {
  color: #525252;
  text-decoration: none;
  transition: color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.breadcrumb__link:hover {
  color: #0a0a0a;
}

.breadcrumb__link:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: 2px;
  border-radius: 4px;
}

.breadcrumb__page {
  color: #0a0a0a;
  font-weight: 500;
}

.breadcrumb__separator {
  color: #525252;
  display: inline-flex;
  align-items: center;
}

.breadcrumb__separator svg {
  width: 1em;
