/* -------------------------------------------------------------------------
   Burger Icon

   Three-line icon for use inside IconButton.
   CSS transition burger ↔ X. GSAP opt-in via [data-menu-button-animate].

   States: [data-menu-button="burger"] (default), [data-menu-button="close"]
   Parts:  .burger-icon, .burger-icon__line
   ------------------------------------------------------------------------- */

/* ---- Icon container ---- */

.burger-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.1875em;
  width: 100%;
  height: 100%;
}

/* ---- Lines ---- */

.burger-icon__line {
  width: 1.25em;
  height: 0.125em;
  background-color: currentColor;
  border-radius: 9999px;
  transform-origin: center;
  transition:
    transform 300ms cubic-bezier(0.4, 0, 0.2, 1),
    opacity 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* ---- CSS-only X state ---- */

[data-menu-button="close"] .burger-icon__line:nth-child(1) {
  transform: translateY(0.3125em) rotate(135deg);
}

[data-menu-button="close"] .burger-icon__line:nth-child(2) {
  opacity: 0;
  transform: scaleX(0);
}

[data-menu-button="close"] .burger-icon__line:nth-child(3) {
  transform: translateY(-0.3125em) rotate(-135deg);
}

/* ---- GSAP mode: disable CSS transitions ---- */

[data-menu-button-animate] .burger-icon__line {
  transition: none;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .burger-icon__line {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Calendar

   Date picker grid. Month navigation, day selection.
   Modes: single, range.

   Parts: .calendar, .calendar__nav, .calendar__nav-btn,
          .calendar__title, .calendar__grid, .calendar__head,
          .calendar__row, .calendar__day
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.calendar {
  display: inline-flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 12.8px;
}

/* ---- Navigation ---- */

.calendar__nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.calendar__title {
  font-size: 12.8px;
  font-weight: 600;
  color: #0a0a0a;
}

/* ---- Grid ---- */

.calendar__grid {
  border-collapse: collapse;
}

.calendar__head {
  font-size: 10.24px;
  font-weight: 500;
  color: #525252;
  text-align: center;
  padding-bottom: 8px;
  width: 36px;
}

/* ---- Day cell ---- */

.calendar__day {
  width: 36px;
  height: 36px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: none;
  color: #0a0a0a;
  font-family: inherit;
  font-size: 12.8px;
  font-weight: 400;
  line-height: 1;
  text-align: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 100ms cubic-bezier(0.4, 0, 0.2, 1);
}

.calendar__day:hover:not(.calendar__day--disabled):not(.calendar__day--selected) {
  background-color: #f5f5f5;
  color: #171717;
}

.calendar__day:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: -2px;
}

/* Outside month */
.calendar__day--outside {
  color: #525252;
  opacity: 0.5;
}

/* Today */
.calendar__day--today {
  font-weight: 600;
  color: #0a0a0a;
  box-shadow: inset 0 -2px 0 #0a0a0a;
}

/* Selected */
.calendar__day--selected {
  background-color: #0a0a0a;
  color: #fafafa;
  font-weight: 500;
}

.calendar__day--selected:hover {
  background-color: #262626;
}

/* Range: start + end */
.calendar__day--range-start {
  border-radius: 8px 0 0 8px;
}

.calendar__day--range-end {
  border-radius: 0 8px 8px 0;
}

.calendar__day--range-start.calendar__day--range-end {
  border-radius: 8px;
}

/* Range: middle */
.calendar__day--in-range {
  background-color: #f5f5f5;
  color: #171717;
  border-radius: 0;
}

/* Disabled */
.calendar__day--disabled {
  color: #525252;
  opacity: 0.3;
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .calendar__day {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Chip

   Interactive tag with optional leading icon and close button.
   Same sizing discipline as Button: height + padding from tokens,
   gap/radius/icon em-relative.

   Types:   outlined, filled
   Sizes:   xs, s, m, l, xl (same naming as Button)
   States:  enabled, hover, pressed, disabled, error
   ------------------------------------------------------------------------- */

.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.375em;
  border-radius: 0.5em;
  border: 1.5px solid transparent;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 10.24px;
  font-weight: 500;
  line-height: 1;
  color: #0a0a0a;
  cursor: default;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  white-space: nowrap;
  transition:
    background-color 150ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 150ms cubic-bezier(0.22, 1, 0.36, 1),
    scale 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.chip[data-chip-animate]:active:not(.chip--disabled) {
  scale: 0.955 0.925;
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .chip[data-chip-animate]:hover:not(.chip--disabled) {
    scale: 1.06 1.095;
    transition:
      background-color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
      border-color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
      scale 500ms 0.05s cubic-bezier(0.32, 0.72, 0, 1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .chip {
    transition-duration: 0ms;
  }
  .chip:active:not(.chip--disabled) {
    scale: 1;
  }
}

/* ---- Sizes (height + h-padding explicit, font-size uniform) ---- */

.chip--xs {
  height: 1.25rem;
  padding: 0 4px;
}

.chip--s {
  height: 1.5rem;
  padding: 0 8px;
}

.chip--m {
  height: 2rem;
  padding: 0 8px;
}

.chip--l {
  height: 2.5rem;
  padding: 0 12px;
}

.chip--xl {
  height: 3rem;
  padding: 0 16px;
}

/* ---- Types ---- */

.chip--outlined {
  background-color: #fafafa;
  border-color: #e5e5e5;
}

.chip--outlined:hover:not(.chip--disabled) {
  background-color: #f5f5f5;
}

.chip--filled {
  background-color: #f5f5f5;
}

.chip--filled:hover:not(.chip--disabled) {
  background-color: #f5f5f5;
}

/* ---- Disabled ---- */

.chip--disabled {
  color: #525252;
  cursor: not-allowed;
  pointer-events: none;
}

.chip--disabled.chip--outlined {
  border-color: #f5f5f5;
  background-color: #f5f5f5;
}

.chip--disabled.chip--filled {
  background-color: #f5f5f5;
}

/* ---- Error ---- */

.chip--error.chip--outlined {
  border-color: #f84131;
  color: #f84131;
}

.chip--error.chip--outlined:hover:not(.chip--disabled) {
  background-color: color-mix(in srgb, #f84131 6%, #fafafa);
}

.chip--error.chip--filled {
  background-color: color-mix(in srgb, #f84131 8%, #fafafa);
  color: #f84131;
}

.chip--error.chip--filled:hover:not(.chip--disabled) {
  background-color: color-mix(in srgb, #f84131 12%, #fafafa);
}

/* ---- Focus ---- */

.chip:focus-visible,
.chip--focused {
  box-shadow: 0 0 0 2px var(--focus-ring-color);
  outline: none;
}

/* ---- Parts ---- */

.chip__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
}

.chip__icon svg {
  width: 100%;
  height: 100%;
}

.chip__label {
  display: inline-flex;
  align-items: center;
}

.chip__close {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.125em;
  height: 1.125em;
  padding: 0.125em;
  border: none;
  background-color: color-mix(in srgb, #0a0a0a 6%, transparent);
  color: inherit;
  cursor: pointer;
  border-radius: 9999px;
  transition:
    background-color 150ms cubic-bezier(0.22, 1, 0.36, 1),
    scale 500ms cubic-bezier(0.32, 0.72, 0, 1);
}

.chip__close svg {
  width: 100%;
  height: 100%;
}

.chip__close:active {
  scale: 0.9;
}

.chip--error .chip__close {
  background-color: color-mix(in srgb, #f84131 10%, transparent);
}

.chip--disabled .chip__close {
  cursor: not-allowed;
  pointer-events: none;
  background-color: color-mix(in srgb, #0a0a0a 4%, transparent);
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .chip__close:hover {
    background-color: color-mix(in srgb, #0a0a0a 12%, transparent);
    scale: 1.06 1.095;
  }

  .chip--error .chip__close:hover {
    background-color: color-mix(in srgb, #f84131 18%, transparent);
  }
}

/* -------------------------------------------------------------------------
   Combobox

   Searchable select. Trigger + floating listbox with filter input.
   Composable: Combobox > Trigger + Content > Input + List > Item

   Parts: .combobox, .combobox__trigger, .combobox__content,
          .combobox__input, .combobox__list, .combobox__item,
          .combobox__group, .combobox__group-label, .combobox__empty
   ------------------------------------------------------------------------- */

/* ---- Root ---- */

.combobox {
  position: relative;
  display: inline-flex;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
}

/* ---- Trigger ---- */

.combobox__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  height: 40px;
  padding: 0 12px;
  border: 1px solid #d4d4d4;
  border-radius: 8px;
  background-color: #fafafa;
  color: #0a0a0a;
  font-family: inherit;
  font-size: 12.8px;
  font-weight: 400;
  line-height: 1;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    border-color 150ms cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.combobox__trigger:hover {
  border-color: #171717;
}

.combobox__trigger:focus-visible {
  border-color: #171717;
  box-shadow: 0 0 0 2px var(--focus-ring-color);
  outline: none;
}

.combobox__trigger--open {
  border-color: #171717;
  box-shadow: 0 0 0 2px var(--focus-ring-color);
}

.combobox__trigger--disabled {
  background-color: #f5f5f5;
  border-color: #f5f5f5;
  color: #525252;
  cursor: not-allowed;
  pointer-events: none;
}

.combobox__trigger[aria-invalid="true"] {
  border-color: #f84131;
  box-shadow: 0 0 2px 0 var(--focus-ring-error-color);
}

.combobox__trigger[aria-invalid="true"]:focus-visible,
.combobox__trigger[aria-invalid="true"].combobox__trigger--open {
  border-color: #f84131;
  box-shadow: 0 0 0 2px var(--focus-ring-error-color);
}

.combobox__trigger-text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.combobox__trigger-text--placeholder {
  color: #525252;
}

.combobox__trigger-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
  color: #525252;
  transition: transform 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

.combobox__trigger--open .combobox__trigger-icon {
  transform: rotate(180deg);
}

/* ---- Content (floating panel) ---- */

.combobox__content {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  z-index: 20;
  width: 100%;
  min-width: 200px;
  overflow: hidden;
  border: 1px solid #e5e5e5;
  border-radius: 12px;
  background-color: #ffffff;
  color: #0a0a0a;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  transform-origin: top;
  animation: combobox-in 200ms cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes combobox-in {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(-4px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* ---- Search input inside content ---- */

.combobox__input-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid #e5e5e5;
}

.combobox__input-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
  color: #525252;
}

.combobox__input {
  flex: 1;
  min-width: 0;
  border: none;
  background: none;
  color: #0a0a0a;
  font-family: inherit;
  font-size: 12.8px;
  line-height: 1;
  outline: none;
  padding: 0;
}

.combobox__input::placeholder {
  color: #525252;
}

/* ---- List ---- */

.combobox__list {
  max-height: 240px;
  overflow-y: auto;
  padding: 4px;
}

/* ---- Empty state ---- */

.combobox__empty {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 8px;
  color: #525252;
  font-size: 12.8px;
}

/* ---- Group ---- */

.combobox__group-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.combobox__group-label {
  padding: 8px 8px 4px;
  font-size: 10.24px;
  font-weight: 500;
  color: #525252;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ---- Item ---- */

.combobox__item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px;
  border: none;
  border-radius: 4px;
  background: none;
  color: #0a0a0a;
  font-family: inherit;
  font-size: 12.8px;
  line-height: 1;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 100ms cubic-bezier(0.4, 0, 0.2, 1);
}

.combobox__item:hover,
.combobox__item--highlighted {
  background-color: #f5f5f5;
  color: #171717;
}

.combobox__item--selected {
  font-weight: 500;
}

.combobox__item--disabled {
  color: #525252;
  cursor: not-allowed;
  pointer-events: none;
}

.combobox__item:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: -2px;
  border-radius: 4px;
}

/* ---- Separator ---- */

.combobox__separator {
  height: 1px;
  margin: 4px calc(-1 * 4px);
  background-color: #e5e5e5;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .combobox__trigger,
  .combobox__trigger-icon,
  .combobox__item {
    transition-duration: 0ms;
  }

  .combobox__content {
    animation-duration: 0ms;
  }
}

