/* -------------------------------------------------------------------------
   Marquee

   Infinite horizontal scroll. CSS animation, JS for speed + duplication.
   Pauses when out of viewport. Hover pauses optional.

   Parts: .marquee, .marquee__list, .marquee__item
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.marquee {
  display: flex;
  position: relative;
  overflow: hidden;
  width: 100%;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
}

/* ---- Fade edges ---- */

.marquee--fade {
  mask-image: linear-gradient(
    to right,
    transparent,
    black 40px,
    black calc(100% - 40px),
    transparent
