  -webkit-mask-image: linear-gradient(
    to right,
    transparent,
    black 40px,
    black calc(100% - 40px),
    transparent
  );
}

/* ---- List (duplicated by JS) ---- */

/* stretch y no center: los items miden lo mismo que el mas alto de la fila, y
   cada uno decide dentro como coloca su contenido (.marquee__item sigue
   centrando el suyo, asi que una tira de logos no cambia). Es lo que permite
   que una fila de cards se lea pareja aunque una lleve mas texto. */
.marquee__list {
  flex: none;
  display: flex;
  align-items: stretch;
  animation: marquee-scroll 30s linear infinite;
  animation-play-state: running;
}

.marquee--reverse .marquee__list {
  animation-direction: reverse;
}

.marquee--pause-hover:hover .marquee__list {
  animation-play-state: paused;
}

@keyframes marquee-scroll {
  to {
    transform: translateX(-100%);
  }
}

/* ---- Item ---- */

.marquee__item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  flex-shrink: 0;
  white-space: nowrap;
}

/* ---- Logos mode ----
   Tira de marcas de cliente. Los logos llegan con proporciones y pesos opticos
   dispares, asi que la unica medida que se puede igualar por CSS es la ALTURA;
   lo demas es correccion caso por caso.

   --marquee-logo-scale existe justo para eso. La correccion optica que vivia en
   prod la hacia un embed con selectores por nombre de archivo
   (img[src*="toyota"] { transform: scale(.76) }): se rompia al renombrar el
   asset y era invisible desde el panel. Como variable por item, la pone quien
   edita y sobrevive al asset.

   OJO en Webflow: el panel del Designer no declara custom properties y rechaza
   el atributo style, asi que ahi la correccion va como combo class por marca
   con la altura ya multiplicada (.ds-marquee__logo.ds-logo--toyota
   { height: 2.66rem }), que gana por especificidad. La variable sigue siendo el
   contrato para React y CLI. */

.marquee__logo {
  display: block;
  /* La correccion optica multiplica la ALTURA, no un transform: scale().
     Un transform no cambia la caja: el logo corregido al alza se sale de su
     item y se monta sobre el siguiente, y el hueco corregido a la baja queda
     de mas. Se veia sobre todo al reiniciar el ciclo, porque ahi coinciden el
     ultimo item de una lista y el primero de la siguiente. Con height la caja
     crece o encoge con el logo y el ritmo del carril vuelve a ser real. */
  height: calc(3rem * 1);
  width: auto;
  /* Webflow sirve img { max-width: 100% } de fabrica: sin esto, un wordmark
     ancho se comprime en vez de respetar su altura. */
  max-width: none;
  object-fit: contain;
}

/* El espaciado sigue el modelo del marquee de Osmo: el padding del item va a UN
   SOLO lado. Con padding en los dos, el hueco entre logos es el DOBLE del valor
   declarado y el primer logo entra despegado del borde de la seccion; con un
   solo lado, el valor declarado ES el hueco y la tira arranca a ras.
   El default de .marquee__item (12/16px) sirve para texto, no para marcas:
   dos logos separados por 32px se leen como un logo compuesto.

   Va como modificador del ITEM y no como modo del carril (.marquee--logos ...)
   por el canal de Webflow: el panel del Designer no declara selectores
   descendentes, asi que un modo en el contenedor no se puede reproducir ahi y
   la tira quedaria sin espaciado en el canvas. Como combo class del item, si.

   Sin separador entre logos: se probo un punto de acento y en una tira de
   marcas ajenas mete un tercer color que compite con cada logo. El ritmo lo
   marca el hueco. */
.marquee__item--logo {
  padding-block: 16px;
  padding-inline: 0 var(--spacing-10);
}

/* Insignia: mas alta que un logo de cliente porque no es una marca, es un sello
   —G2, Meta, HubSpot— y lleva texto dentro que a 3.5rem no se lee.

   Va como modificador y no como --marquee-logo-height en el consumidor porque
   el panel de Webflow no declara custom properties: alli una variable no se
   puede pasar, un combo class si. */
.marquee__logo--badge {
  height: 5rem;
}

/* ---- Separator (optional decorative element between items) ---- */

.marquee__separator {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: #525252;
}

.marquee__separator svg {
  width: 1em;
  height: 1em;
}

/* ---- Draggable mode (GSAP) ---- */

/* En modo draggable el desplazamiento lo pone GSAP sobre __collection. La
   animacion CSS de __list seguiria corriendo sobre el MISMO eje y sumaria un
   segundo movimiento: la tira avanza al doble y el wrap de GSAP deja de cuadrar
