.marquee--draggable .marquee__list {
  animation: none;
}

.marquee__collection {
  display: flex;
  align-items: stretch;
  flex: none;
  will-change: transform;
  cursor: grab;
}

.marquee__collection:active {
  cursor: grabbing;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .marquee__list {
    animation-play-state: paused;
  }
}

