/* -------------------------------------------------------------------------
   Pagination

   Page navigation: prev, page links, ellipsis, next.
   Semantic <nav> + <ul> structure.

   Parts: .pagination, .pagination__list, .pagination__item,
          .pagination__link, .pagination__ellipsis
   ------------------------------------------------------------------------- */

/* ---- Nav ---- */

.pagination {
  display: flex;
  justify-content: center;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
}

/* ---- List ---- */

.pagination__list {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ---- Link ---- */

.pagination__link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: none;
  color: #0a0a0a;
  font-family: inherit;
  font-size: 12.8px;
  font-weight: 500;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background-color 100ms cubic-bezier(0.4, 0, 0.2, 1),
    border-color 100ms cubic-bezier(0.4, 0, 0.2, 1);
}

.pagination__link:hover {
  background-color: #f5f5f5;
  color: #171717;
}

.pagination__link:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: -2px;
}

/* Active page */
.pagination__link--active {
  border-color: #e5e5e5;
  background-color: #fafafa;
  font-weight: 600;
}

/* Disabled (prev/next at bounds) */
.pagination__link--disabled {
  color: #525252;
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Nav icon ---- */

.pagination__link-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1em;
  height: 1em;
}

.pagination__link-icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Ellipsis ---- */

.pagination__ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  color: #525252;
  font-size: 12.8px;
  letter-spacing: 0.04em;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .pagination__link {
    transition-duration: 0ms;
  }
}

