/* ============================================================
   ProgressNav — fixed one-page navigation with scroll indicator
   Uses GSAP ScrollTrigger via @atom-uikit/animations
   ============================================================ */

.progress-nav {
  width: 100%;
  padding: 24px;
  position: fixed;
  top: 0;
  left: 0;
  z-index: 30;
}

.progress-nav__inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
}

/* ---- Logo ---- */
.progress-nav__logo {
  color: inherit;
  text-decoration: none;
  display: flex;
  align-items: center;
}

.progress-nav__logo-svg {
  width: 8em;
  height: auto;
}

/* ---- Pill wrapper (contains the nav list) ---- */
.progress-nav__wrapper {
  background-color: #f5f5f5;
  border-radius: 9999px;
  padding: 4px;
}

/* ---- Nav list ---- */
.progress-nav__list {
  border-radius: 9999px;
  display: flex;
  justify-content: flex-start;
  align-items: center;
  position: relative;
  overflow: hidden;
}

/* ---- Sliding indicator ---- */
.progress-nav__indicator {
  z-index: 2;
  background-color: #ffffff;
  border-radius: 9999px;
  width: 2.5em;
  height: 2.5em;
  position: absolute;
  left: -2.5em;
  transition: all 700ms cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
}

/* ---- Nav buttons ---- */
.progress-nav__btn {
  z-index: 3;
  cursor: pointer;
  color: inherit;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 2.5em;
  padding-left: 1em;
  padding-right: 1em;
  text-decoration: none;
  position: relative;
  overflow: hidden;
}

/* Hidden sentinel buttons (before/after) */
.progress-nav__btn.is--before {
  z-index: 1;
  width: 2.5em;
  height: 2.5em;
  padding: 0;
  position: absolute;
  right: 100%;
}

.progress-nav__btn.is--after {
  z-index: 1;
  width: 2.5em;
  height: 2.5em;
  padding: 0;
  position: absolute;
  left: 100%;
}

/* ---- Text with hover slide animation ---- */
.progress-nav__btn-text {
  white-space: nowrap;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
  font-size: 16px;
  font-weight: 500;
  transition: transform 500ms cubic-bezier(0.16, 1, 0.3, 1);
  transform: translateY(0%) rotate(0.001deg);
}

.progress-nav__btn-text.is--duplicate {
  position: absolute;
  top: 100%;
}

.progress-nav__btn:hover .progress-nav__btn-text,
.progress-nav__contact-btn:hover .progress-nav__btn-text {
  transform: translateY(-100%) rotate(0.001deg);
}

/* ---- CTA button ---- */
.progress-nav__contact-btn {
  color: #fafafa;
  background-color: #0a0a0a;
  border-radius: 9999px;
  height: 3.5em;
  padding-left: 24px;
  padding-right: 24px;
  text-decoration: none;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  transition: background-color 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

.progress-nav__contact-btn:hover {
  background-color: #262626;
}

/* ---- Reduced motion ---- */
@media (prefers-reduced-motion: reduce) {
  .progress-nav__indicator {
    transition-duration: 0ms;
  }
  .progress-nav__btn-text {
    transition-duration: 0ms;
  }
  .progress-nav__contact-btn {
    transition-duration: 0ms;
  }
}

