derived.standaloneCss:
/* -------------------------------------------------------------------------
   Resizable

   Draggable panel layout. Horizontal or vertical.
   Keyboard accessible (Arrow keys to resize).

   Parts: .resizable, .resizable__panel, .resizable__handle
   ------------------------------------------------------------------------- */

/* ---- Group ---- */

.resizable {
  display: flex;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.resizable--vertical {
  flex-direction: column;
}

/* ---- Panel ---- */

.resizable__panel {
  overflow: auto;
  min-width: 0;
  min-height: 0;
}

/* ---- Handle ---- */

.resizable__handle {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: none;
  border: none;
  padding: 0;
  cursor: col-resize;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.resizable--vertical .resizable__handle {
  cursor: row-resize;
}

/* Horizontal handle: thin vertical bar */
.resizable:not(.resizable--vertical) > .resizable__handle {
  width: 8px;
}

/* Vertical handle: thin horizontal bar */
.resizable--vertical > .resizable__handle {
  height: 8px;
}

.resizable__handle:hover {
  background-color: #f5f5f5;
}

.resizable__handle:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: -2px;
}

/* ---- Visible grip ---- */

.resizable__handle-grip {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  background-color: #e5e5e5;
}

.resizable:not(.resizable--vertical) .resizable__handle-grip {
  width: 4px;
  height: 24px;
}

.resizable--vertical .resizable__handle-grip {
  width: 24px;
  height: 4px;
}

/* ---- Active drag state ---- */

.resizable__handle--dragging {
  background-color: #f5f5f5;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .resizable__handle {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Sheet

   Side panel extending Dialog. Slides from screen edge.
   Reuses dialog__overlay for backdrop.

   Sides: top, right, bottom, left
   Parts: .sheet, .sheet__header, .sheet__title,
          .sheet__description, .sheet__body, .sheet__footer, .sheet__close
   ------------------------------------------------------------------------- */

/* ---- Content ---- */

.sheet {
  position: fixed;
  z-index: 50;
  display: flex;
  flex-direction: column;
  background-color: #ffffff;
  color: #0a0a0a;
  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  border: 1px solid #e5e5e5;
}

.sheet--exiting {
  pointer-events: none;
}

/* ---- Sides ---- */

.sheet--right {
  top: 0; right: 0; bottom: 0;
  width: 100%;
  max-width: 400px;
  border-left: 1px solid #e5e5e5;
  border-right: none;
  animation: sheet-right-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}
.sheet--right.sheet--exiting {
  animation: sheet-right-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

.sheet--left {
  top: 0; left: 0; bottom: 0;
  width: 100%;
  max-width: 400px;
  border-right: 1px solid #e5e5e5;
  border-left: none;
  animation: sheet-left-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}
.sheet--left.sheet--exiting {
  animation: sheet-left-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

.sheet--top {
  top: 0; left: 0; right: 0;
  height: auto;
  max-height: 80vh;
  border-bottom: 1px solid #e5e5e5;
  border-top: none;
  animation: sheet-top-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}
.sheet--top.sheet--exiting {
  animation: sheet-top-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

.sheet--bottom {
  bottom: 0; left: 0; right: 0;
  height: auto;
  max-height: 80vh;
  border-top: 1px solid #e5e5e5;
  border-bottom: none;
  animation: sheet-bottom-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}
.sheet--bottom.sheet--exiting {
  animation: sheet-bottom-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

/* ---- Slide animations ---- */

@keyframes sheet-right-in  { from { transform: translateX(100%); } to { transform: translateX(0); } }
@keyframes sheet-right-out { from { transform: translateX(0); } to { transform: translateX(100%); } }
@keyframes sheet-left-in   { from { transform: translateX(-100%); } to { transform: translateX(0); } }
@keyframes sheet-left-out  { from { transform: translateX(0); } to { transform: translateX(-100%); } }
@keyframes sheet-top-in    { from { transform: translateY(-100%); } to { transform: translateY(0); } }
@keyframes sheet-top-out   { from { transform: translateY(0); } to { transform: translateY(-100%); } }
@keyframes sheet-bottom-in { from { transform: translateY(100%); } to { transform: translateY(0); } }
@keyframes sheet-bottom-out { from { transform: translateY(0); } to { transform: translateY(100%); } }

/* ---- Header ---- */

.sheet__header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 24px;
  padding-bottom: 0;
}

.sheet__title {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.45;
  color: #0a0a0a;
  margin: 0;
}

.sheet__description {
  font-size: 12.8px;
  line-height: 1.45;
  color: #525252;
  margin: 0;
}

/* ---- Body ---- */

.sheet__body {
  flex: 1;
  overflow-y: auto;
  padding: 24px;
}

/* ---- Footer ---- */

.sheet__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  padding: 24px;
  padding-top: 0;
}

/* ---- Close ---- */

.sheet__close {
  position: absolute;
  top: 16px;
  right: 16px;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .sheet,
  .sheet--exiting {
    animation-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Slider

   Range input. Drag thumb along track to select value.
   Supports single value and range (two thumbs).

   Parts: .slider, .slider__track, .slider__range, .slider__thumb
   ------------------------------------------------------------------------- */

/* ---- Root ---- */

.slider {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  touch-action: none;
  user-select: none;
  cursor: pointer;
}

/* ---- Track ---- */

.slider__track {
  position: relative;
  width: 100%;
  height: 8px;
  border-radius: 9999px;
  background-color: #f5f5f5;
  overflow: hidden;
}

/* ---- Range (filled portion) ---- */

.slider__range {
  position: absolute;
  height: 100%;
  background-color: #0a0a0a;
  border-radius: 9999px;
}

/* ---- Thumb ---- */

.slider__thumb {
  position: absolute;
  top: 50%;
  width: 20px;
  height: 20px;
  border-radius: 9999px;
  border: 2px solid #0a0a0a;
  background-color: #fafafa;
  transform: translate(-50%, -50%);
  cursor: grab;
  transition:
    box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1),
    scale 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.slider__thumb:hover {
  box-shadow: 0 0 0 8px color-mix(in srgb, #0a0a0a 4%, transparent);
}

.slider__thumb:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: 2px;
}

.slider__thumb:active,
.slider__thumb--dragging {
  cursor: grabbing;
  scale: 1.1;
}

/* ---- Disabled ---- */

.slider--disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .slider__thumb {
    transition-duration: 0ms;
  }
}

/* ============================================================
   StatsCard — metric number + label + optional trend indicator
   ============================================================ */

.stats-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 32px;
  border-radius: 16px;
  background-color: #ffffff;
  border: 1px solid #e5e5e5;
  transition: border-color 150ms cubic-bezier(0.22, 1, 0.36, 1);
}

.stats-card--compact {
  padding: 16px;
  gap: 8px;
  border-radius: 12px;
}

/* ---- Value (big number) ---- */
.stats-card__value {
  font-size: 48.83px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  color: #0a0a0a;
  font-variant-numeric: tabular-nums;
}

.stats-card--compact .stats-card__value {
  font-size: 31.25px;
}

.stats-card--gradient .stats-card__value {
  /* fallback keeps standalone installs working without the utilities item */
  background: linear-gradient(135deg, var(--color-forest 0%, #ff6600 100%));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* ---- Label ---- */
.stats-card__label {
  font-size: 12.8px;
  font-weight: 500;
  color: #525252;
  line-height: 1.4;
}

/* ---- Trend indicator ---- */
.stats-card__trend {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10.24px;
  font-weight: 500;
  line-height: 1;
  margin-top: 4px;
}

.stats-card__trend--up {
  color: #25d366;
}

.stats-card__trend--down {
  color: #f84131;
}

.stats-card__trend--neutral {
  color: #525252;
}

.stats-card__trend-icon {
  display: flex;
  width: 1em;
  height: 1em;
}

.stats-card__trend-icon svg {
  width: 100%;
  height: 100%;
}

