/* -------------------------------------------------------------------------
   Toast (Sonner)

   Notification toasts. Fixed container, imperative API.
   Auto-dismiss, close button, description, action support.

   Variants: default, success, info, warning, error
   Positions: top-left, top-center, top-right,
              bottom-left, bottom-center, bottom-right

   Parts: .toaster, .toast, .toast__content, .toast__title,
          .toast__description, .toast__close, .toast__action
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.toaster {
  position: fixed;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
  max-width: 420px;
  width: 100%;
  padding: 16px;
}

.toaster--top-left      { top: 0; left: 0; align-items: flex-start; }
.toaster--top-center    { top: 0; left: 50%; transform: translateX(-50%); align-items: center; }
.toaster--top-right     { top: 0; right: 0; align-items: flex-end; }
.toaster--bottom-left   { bottom: 0; left: 0; align-items: flex-start; }
.toaster--bottom-center { bottom: 0; left: 50%; transform: translateX(-50%); align-items: center; }
.toaster--bottom-right  { bottom: 0; right: 0; align-items: flex-end; }

/* ---- Toast ---- */

.toast {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  max-width: 380px;
  padding: 16px;
  border: 1px solid #e5e5e5;
  border-radius: 12px;
  background-color: #ffffff;
  color: #0a0a0a;
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  pointer-events: auto;
  animation: toast-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}

.toast--exiting {
  animation: toast-out 200ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

/* ---- Variants ---- */

.toast--success {
  border-color: #25d366;
  background-color: #25d366;
  color: #0a0a0a;
}

.toast--error {
  border-color: #f84131;
  background-color: #f84131;
  color: #0a0a0a;
}

.toast--warning {
  border-color: #fe9900;
  background-color: #fe9900;
  color: #471901;
}

.toast--info {
  border-color: #22d3ee;
  background-color: #22d3ee;
  color: #0a0a0a;
}

/* ---- Icon ---- */

.toast__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.25em;
  height: 1.25em;
}

.toast__icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Content ---- */

.toast__content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

/* ---- Title ---- */

.toast__title {
  font-size: 12.8px;
  font-weight: 600;
  line-height: 1.45;
}

/* ---- Description ---- */

.toast__description {
  font-size: 12.8px;
  line-height: 1.45;
  opacity: 0.8;
}

/* ---- Close button (IconButton override) ---- */

.toast__close {
  flex-shrink: 0;
  color: inherit;
  opacity: 0.5;
}

.toast__close:hover {
  opacity: 1;
}

/* ---- Action button (Button override) ---- */

.toast__action {
  align-self: flex-start;
  margin-top: 4px;
}

/* ---- Animations ---- */

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes toast-out {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateY(-8px) scale(0.96);
  }
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .toast,
  .toast--exiting {
    animation-duration: 0ms;
  }

  .toast__close,
  .toast__action {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Toggle Group

   Selectable button group. Single or multiple selection.
   Extends button-group layout with active state.

   Variants: default (ghost bg), outline (border)
   Sizes:    xs, s, m, l
   Parts:    .toggle-group, .toggle-group__item
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.toggle-group {
  display: inline-flex;
  align-items: stretch;
  gap: 4px;
  border-radius: 8px;
}

.toggle-group--vertical {
  flex-direction: column;
}

.toggle-group--outline {
  gap: 0;
}

/* ---- Item ---- */

.toggle-group__item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  border-radius: 8px;
  background: none;
  color: #525252;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 12.8px;
  font-weight: 500;
  line-height: 1;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background-color 150ms cubic-bezier(0.4, 0, 0.2, 1),
    color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.toggle-group__item:hover {
  background-color: #f5f5f5;
  color: #0a0a0a;
}

.toggle-group__item:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: calc(-1 * 2px);
  border-radius: 8px;
}

/* Active — follows button primary convention */

.toggle-group__item--active {
  background-color: #0a0a0a;
  color: #fafafa;
}

/* Disabled */

.toggle-group__item--disabled {
  color: #525252;
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Icon ---- */

.toggle-group__item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
}

.toggle-group__item-icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Sizes ---- */

.toggle-group__item--xs { height: 1.75rem; padding: 0 8px; }
.toggle-group__item--s  { height: 2rem; padding: 0 12px; }
.toggle-group__item--m  { height: 2.5rem; padding: 0 12px; }
.toggle-group__item--l  { height: 3rem; padding: 0 16px; }

/* Icon-only (square) */
.toggle-group__item--icon-only.toggle-group__item--xs { width: 1.75rem; padding: 0; }
.toggle-group__item--icon-only.toggle-group__item--s  { width: 2rem; padding: 0; }
.toggle-group__item--icon-only.toggle-group__item--m  { width: 2.5rem; padding: 0; }
.toggle-group__item--icon-only.toggle-group__item--l  { width: 3rem; padding: 0; }

/* ---- Outline variant ---- */

.toggle-group--outline .toggle-group__item {
  border: 1px solid #e5e5e5;
  border-radius: 0;
}

.toggle-group--outline:not(.toggle-group--vertical) .toggle-group__item + .toggle-group__item {
  margin-left: calc(-1 * 1px);
}

.toggle-group--outline:not(.toggle-group--vertical) .toggle-group__item:first-child {
  border-radius: 8px 0 0 8px;
}

.toggle-group--outline:not(.toggle-group--vertical) .toggle-group__item:last-child {
  border-radius: 0 8px 8px 0;
}

.toggle-group--outline.toggle-group--vertical .toggle-group__item + .toggle-group__item {
  margin-top: calc(-1 * 1px);
}

.toggle-group--outline.toggle-group--vertical .toggle-group__item:first-child {
  border-radius: 8px 8px 0 0;
}

.toggle-group--outline.toggle-group--vertical .toggle-group__item:last-child {
  border-radius: 0 0 8px 8px;
}

/* ---- Animation (opt-in) ---- */

.toggle-group__item-icon {
  transition: rotate 500ms cubic-bezier(0.19, 1, 0.22, 1);
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .toggle-group[data-toggle-group-animate] .toggle-group__item:hover:not(.toggle-group__item--disabled) {
    scale: 1.095;
  }

  .toggle-group[data-toggle-group-animate] .toggle-group__item:hover:not(.toggle-group__item--disabled) .toggle-group__item-icon {
    rotate: 360deg;
    transition: rotate 0.6s 0.05s cubic-bezier(0.19, 1, 0.22, 1);
  }
}

.toggle-group__item:active:not(.toggle-group__item--disabled) {
  scale: 0.925;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .toggle-group__item,
  .toggle-group__item-icon {
    transition-duration: 0ms;
  }

  .toggle-group__item:active {
    scale: 1;
  }
}

