/* -------------------------------------------------------------------------
   User Profile (Molecule)

   Avatar + name + org/role in a row. Collapses to avatar-only
   when parent constrains width (e.g., sidebar collapsed).

   Composes: Avatar atom.
   Used in: sidebar footer, dropdowns, settings pages.
   ------------------------------------------------------------------------- */

.user-profile {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
  cursor: pointer;
  padding: 4px;
  border-radius: 8px;
  text-decoration: none;
  transition: background-color 0.15s cubic-bezier(0.19, 1, 0.22, 1);
}

.user-profile:hover {
  background-color: #f5f5f5;
}

.user-profile__info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow: hidden;
  min-width: 0;
  transition: opacity 0.2s ease, width 0.2s ease;
}

.user-profile__name {
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 12.8px;
  font-weight: 500;
  line-height: 1;
  color: #0a0a0a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.user-profile__org {
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 10.24px;
  font-weight: 400;
  line-height: 1;
  color: #525252;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Collapses in sidebar collapsed state */
.sidebar--collapsed .user-profile__info {
  opacity: 0;
  width: 0;
  overflow: hidden;
}

.sidebar--collapsed .user-profile {
  padding: 4px;
  justify-content: center;
  overflow: visible;
}

/* -------------------------------------------------------------------------
   Video Player

   Custom video player with glass UI controls. Cloudflare Stream.
   State driven by data attributes (framework-agnostic).

   Tokens: --surface-glass, --surface-glass-blur, --surface-dark,
           --surface-dark-overlay, --player-accent, --player-progress-bg,
           --player-foreground

   Parts: .video-player, .video-player__iframe, .video-player__placeholder,
          .video-player__dark, .video-player__play, .video-player__pause,
          .video-player__btn, .video-player__interface,
          .video-player__timeline, .video-player__mute,
          .video-player__fullscreen, .video-player__duration,
          .video-player__loading
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.video-player {
  pointer-events: auto;
  color: var(--player-foreground);
  isolation: isolate;
  background-color: var(--surface-dark);
  border-radius: 16px;
  justify-content: center;
  align-items: center;
  width: 100%;
  display: flex;
  position: relative;
  overflow: hidden;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 12.8px;
}

/* Cover mode */
.video-player[data-video-update-size="cover"] {
  width: 100%;
  height: 100%;
}

/* ---- Aspect ratio spacer ---- */

.video-player__before {
  padding-top: 62.5%;
}

/* ---- Iframe ---- */

.video-player__iframe {
  pointer-events: none;
  width: 100%;
  height: 100%;
  position: absolute;
  border: none;
}

/* ---- Placeholder ---- */

.video-player__placeholder {
  object-fit: cover;
  width: 100%;
  height: 100%;
  display: block;
  position: absolute;
  transition: opacity 300ms linear;
}

.video-player[data-video-activated="true"][data-video-loaded="true"] .video-player__placeholder {
  opacity: 0;
}

/* ---- Dark overlay ---- */

.video-player__dark {
  pointer-events: none;
  background-color: var(--surface-dark);
  width: 100%;
  height: 100%;
  position: absolute;
  transition: opacity 300ms linear;
  opacity: 0.5;
}

.video-player[data-video-playing="false"] .video-player__dark {
  opacity: 0.3;
}

.video-player[data-video-activated="false"][data-video-playing="false"] .video-player__dark {
  opacity: 0;
}

.video-player[data-video-activated="true"][data-video-loaded="true"] .video-player__dark {
  opacity: 0;
}

@media (hover: hover) and (pointer: fine) {
  .video-player[data-video-hover="true"]:hover .video-player__dark {
    opacity: 0.3 !important;
  }
}

/* ---- Play / Pause buttons ---- */

.video-player__play,
.video-player__pause {
  cursor: pointer;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
  position: absolute;
}

/* Glass button */
.video-player__btn {
  -webkit-backdrop-filter: blur(var(--surface-glass-blur));
  backdrop-filter: blur(var(--surface-glass-blur));
  background-color: var(--surface-glass);
  border-radius: 9999px;
  justify-content: center;
  align-items: center;
  width: 6em;
  height: 6em;
  display: flex;
  position: relative;
  transition: opacity 300ms linear;
}

.video-player__btn-play-svg { width: 40%; }
.video-player__btn-pause-svg { width: 50%; }

/* Pause: hidden by default, show when playing */
.video-player .video-player__pause { display: none; }
.video-player[data-video-playing="true"] .video-player__pause { display: flex; }
.video-player .video-player__pause .video-player__btn { opacity: 0; }

.video-player[data-video-activated="true"][data-video-playing="false"] .video-player__pause .video-player__btn,
.video-player[data-video-activated="true"][data-video-hover="true"]:hover .video-player__pause .video-player__btn {
  opacity: 1;
}

@media (hover: none) and (pointer: coarse) {
  .video-player[data-video-activated="true"][data-video-playing="true"] .video-player__pause .video-player__btn {
    opacity: 0 !important;
  }
}

/* Play: hidden when playing */
.video-player[data-video-playing="true"] .video-player__play { opacity: 0; }

/* ---- Loading ---- */

.video-player__loading {
  pointer-events: none;
  color: var(--player-accent);
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  position: absolute;
  display: flex;
  opacity: 0;
  transition: opacity 300ms linear;
}

.video-player__loading-svg { width: 6em; }

.video-player[data-video-playing="true"] .video-player__loading { opacity: 1; }
.video-player[data-video-playing="true"][data-video-loaded="true"] .video-player__loading { opacity: 0; }

/* ---- Interface (controls bar) ---- */

.video-player .video-player__interface { opacity: 0; }

.video-player[data-video-activated="false"][data-video-playing="false"] .video-player__interface { opacity: 1; }

.video-player[data-video-activated="true"][data-video-playing="false"] .video-player__interface,
.video-player[data-video-activated="true"][data-video-hover="true"]:hover .video-player__interface {
  opacity: 1;
}

@media (hover: none) and (pointer: coarse) {
  .video-player[data-video-activated="true"][data-video-playing="true"] .video-player__interface {
    opacity: 0 !important;
  }
}

.video-player__interface {
  pointer-events: none;
  flex-flow: column;
  justify-content: flex-end;
  align-items: stretch;
  width: 100%;
  height: 100%;
  padding: 16px;
  transition: opacity 300ms linear;
  display: flex;
  position: absolute;
}

.video-player__interface * { pointer-events: all; }

.video-player__interface-bottom {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* ---- Timeline ---- */

.video-player__timeline {
  flex-grow: 1;
  justify-content: center;
  align-items: center;
  height: 16px;
  display: flex;
  position: relative;
}

.video-player__timeline-input {
  pointer-events: auto;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  background-color: transparent;
  width: 100%;
  height: 100%;
  display: block;
  position: relative;
}

.video-player__timeline-progress {
  -webkit-appearance: none;
  appearance: none;
  height: 2px;
  border-radius: 9999px;
  color: var(--player-accent);
  background-color: transparent;
  border: none;
  width: 100%;
  margin: 0;
  padding: 0;
  position: absolute;
  left: 0;
  overflow: hidden;
}

.video-player progress::-webkit-progress-bar {
  border-radius: 9999px;
  background-color: var(--player-progress-bg);
}

.video-player progress::-webkit-progress-value {
  background: var(--player-accent);
}

.video-player progress::-moz-progress-bar {
  border-radius: 9999px;
  background: var(--player-accent);
}

/* Range thumb */
.video-player [type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  height: 8px;
  width: 8px;
  border-radius: 9999px;
  background-color: var(--player-accent);
  cursor: pointer;
  margin-top: calc((2px / 2) - (8px / 2));
}

.video-player [type="range"]::-moz-range-thumb {
  border: 0;
  height: 8px;
  width: 8px;
  border-radius: 9999px;
  background: var(--player-accent);
  cursor: pointer;
}

.video-player [type="range"]::-webkit-slider-runnable-track,
.video-player [type="range"]:focus::-webkit-slider-runnable-track {
  background-color: transparent;
  border-color: transparent;
  color: transparent;
}

.video-player [type="range"]::-moz-range-track {
  height: 2px;
  border-radius: 9999px;
  background: var(--player-progress-bg);
  border: 0;
}

.video-player [type="range"]:focus { outline: none; }

/* ---- Mute ---- */

.video-player__mute {
  cursor: pointer;
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  width: 16px;
  height: 16px;
  display: flex;
  position: relative;
}

.video-player__volume-up-svg,
.video-player__volume-mute-svg {
  width: 100%;
  position: absolute;
}

.video-player .video-player__mute svg:nth-child(2),
.video-player[data-video-muted="true"] .video-player__mute svg:nth-child(1) { display: none; }

.video-player .video-player__mute svg:nth-child(1),
.video-player[data-video-muted="true"] .video-player__mute svg:nth-child(2) { display: block; }

/* ---- Fullscreen ---- */

.video-player__fullscreen {
  cursor: pointer;
  justify-content: center;
  align-items: center;
  width: 16px;
  height: 16px;
  display: flex;
  position: relative;
}

.video-player__fullscreen-scale-svg,
.video-player__fullscreen-shrink-svg {
  width: 100%;
  position: absolute;
}

.video-player .video-player__fullscreen svg:nth-child(2),
.video-player[data-video-fullscreen="true"] .video-player__fullscreen svg:nth-child(1) { display: none; }

.video-player .video-player__fullscreen svg:nth-child(1),
.video-player[data-video-fullscreen="true"] .video-player__fullscreen svg:nth-child(2) { display: block; }

/* ---- Duration ---- */

.video-player__duration {
  flex-shrink: 0;
}

.video-player__duration-span {
  text-align: center;
  white-space: nowrap;
  user-select: none;
  font-size: 12.8px;
  font-variant-numeric: tabular-nums;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .video-player__placeholder,
  .video-player__dark,
  .video-player__btn,
  .video-player__loading,
  .video-player__interface {
    transition-duration: 0ms;
  }
}

/* -------------------------------------------------------------------------
   Sidebar

   Composable: Provider (state) + Container + Header/Content/Footer
   Collapse: .sidebar--collapsed toggles layout via CSS
   Labels: [data-sidebar-label] hidden in collapsed via display:none
   Tooltips: [data-tooltip] from tooltip.css, overridden to right/light
   Animations: scale on hover, icon rotation in collapsed

   240px expanded, 48px collapsed. Semantic tokens for colors.
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.sidebar {
  --sidebar-w: 240px;
  --sidebar-w-collapsed: 48px;

  display: flex;
  flex-direction: column;
  width: var(--sidebar-w);
  height: 100%;
  min-height: 100%;
  background: #f5f5f5;
  border-right: 1px solid #efefef;
  flex-shrink: 0;
  transition: width 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.sidebar--collapsed { width: var(--sidebar-w-collapsed); }

/* ---- Sections ---- */

.sidebar__header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 12px;
  flex-shrink: 0;
}

.sidebar__content {
  flex: 1;
  overflow-y: auto;
  padding: 8px;
}

.sidebar__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px;
  flex-shrink: 0;
  margin-top: auto;
  border-top: 1px solid #efefef;
}

.sidebar__divider {
  border: none;
  border-top: 1px solid #e5e5e5;
  margin: 8px 0;
}

/* Collapsed sections */
.sidebar--collapsed .sidebar__header { flex-direction: column; gap: 8px; padding: 8px; align-items: center; }
.sidebar--collapsed .sidebar__content { overflow: visible; padding: 4px; }
.sidebar__footer .dropdown-menu { width: 100%; }
.sidebar__footer .dropdown-menu__trigger { width: 100%; }
.sidebar__footer .dropdown-menu__content { width: 100%; }

.sidebar--collapsed .sidebar__footer { padding: 8px; justify-content: center; }

/* ---- Labels: hide in collapsed ---- */

.sidebar--collapsed [data-sidebar-label] { display: none; }

/* ---- Group ---- */

.sidebar__group { display: flex; flex-direction: column; gap: 2px; }
.sidebar__group + .sidebar__group { margin-top: 24px; }

.sidebar__group-label {
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 10.24px;
  font-weight: 500;
  color: #525252;
  padding: 4px 8px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar--collapsed .sidebar__group-label { display: none; }

/* ---- Item ---- */

.sidebar__item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px;
  height: 36px;
  border-radius: 6px;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 12.8px;
  font-weight: 500;
  line-height: 1;
  color: #0a0a0a;
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  transition:
    background-color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
    color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
    scale 0.45s cubic-bezier(0.32, 0.72, 0, 1);
}

.sidebar__item:hover { background: #f5f5f5; color: #525252; }
.sidebar__item:active:not(.sidebar__item--disabled) { scale: 0.955 0.925; }
.sidebar__item--active { background: #fff4ed; color: #a44200; }
.sidebar__item--disabled { color: #525252; cursor: not-allowed; pointer-events: none; }

/* Item parts */
.sidebar__item-icon { display: flex; align-items: center; justify-content: center; flex-shrink: 0; width: 18px; height: 18px; transition: rotate 0.5s cubic-bezier(0.19, 1, 0.22, 1); }
.sidebar__item-icon svg { width: 100%; height: 100%; }
.sidebar__item-label { flex: 1; overflow: hidden; text-overflow: ellipsis; }
.sidebar__item-badge { font-size: 10.24px; font-weight: 500; color: #525252; flex-shrink: 0; }

/* Collapsed items: icon-only, centered */
.sidebar--collapsed .sidebar__item { justify-content: center; padding: 0; width: 32px; height: 32px; margin: 0 auto; }
.sidebar--collapsed .sidebar__item-label,
.sidebar--collapsed .sidebar__item-badge { display: none; }

/* ---- Hover animations ---- */

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  /* Expanded: subtle Button-style grow */
  .sidebar:not(.sidebar--collapsed) .sidebar__item:hover:not(.sidebar__item--disabled):not(.sidebar__item--active) {
    scale: 1.03 1.05;
  }
  /* Collapsed: IconButton-style scale + icon spin */
  .sidebar--collapsed .sidebar__item:hover:not(.sidebar__item--disabled):not(.sidebar__item--active) {
    scale: 1.095;
  }
  .sidebar--collapsed .sidebar__item:hover .sidebar__item-icon {
    rotate: 360deg;
    transition: rotate 0.6s 0.05s cubic-bezier(0.19, 1, 0.22, 1);
  }
}

/* ---- Trigger ---- */

.sidebar__trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 4px;
  border: none;
  background: #f5f5f5;
  color: #525252;
  cursor: pointer;
  border-radius: 4px;
  flex-shrink: 0;
  transition: background-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.sidebar__trigger:hover { background: #e5e5e5; color: #0a0a0a; }
.sidebar__trigger svg { width: 16px; height: 16px; }

.sidebar--collapsed .sidebar__trigger { background: #f5f5f5; color: #525252; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1); }
.sidebar--collapsed .sidebar__trigger:hover { background: #f5f5f5; color: #525252; }

/* ---- Tooltips (collapsed only) ---- */

.sidebar:not(.sidebar--collapsed) [data-tooltip]::before,
.sidebar:not(.sidebar--collapsed) [data-tooltip]::after { display: none !important; }

.sidebar--collapsed [data-tooltip]::before {
  bottom: auto !important; top: 50% !important;
  left: calc(100% + 10px) !important; right: auto !important;
  transform: translateY(-50%) translateX(-4px) !important;
  background: #fafafa !important; color: #0a0a0a !important;
  border: 1px solid #e5e5e5 !important;
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.1) !important;
}
.sidebar--collapsed [data-tooltip]:hover::before { transform: translateY(-50%) translateX(0) !important; }

.sidebar--collapsed [data-tooltip]::after {
  bottom: auto !important; top: 50% !important;
  left: calc(100% + 7px) !important; right: auto !important;
  transform: translateY(-50%) rotate(225deg) !important;
  background: #fafafa !important;
  border: 1px solid #e5e5e5 !important;
  border-top: none !important; border-left: none !important;
}

/* ---- Collapsible ---- */

.sidebar-collapsible__trigger {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px;
  height: 36px;
  width: 100%;
  border: none;
  background: none;
  border-radius: 6px;
  font-family: 'inter tight', -apple-system, blinkmacsystemfont, 'segoe ui', roboto, helvetica, arial, sans-serif, ui-sans-serif, system-ui, sans-serif;
  font-size: 12.8px;
  font-weight: 500;
  line-height: 1;
  color: #0a0a0a;
  cursor: pointer;
  user-select: none;
  text-align: left;
  white-space: nowrap;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.sidebar-collapsible__trigger:hover { background: #f5f5f5; }
.sidebar-collapsible__label { flex: 1; overflow: hidden; text-overflow: ellipsis; }
.sidebar-collapsible__chevron { display: flex; align-items: center; justify-content: center; flex-shrink: 0; color: #525252; transition: transform 0.2s ease; }

.sidebar-collapsible--open .sidebar-collapsible__chevron { transform: rotate(0deg); }
.sidebar-collapsible:not(.sidebar-collapsible--open) .sidebar-collapsible__chevron { transform: rotate(-90deg); }

/* Collapsible content: animated height */
.sidebar-collapsible__content { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 0.25s cubic-bezier(0.19, 1, 0.22, 1); }
.sidebar-collapsible:not(.sidebar-collapsible--open) .sidebar-collapsible__content { grid-template-rows: 0fr; }
.sidebar-collapsible__inner { overflow: hidden; min-height: 0; display: flex; flex-direction: column; gap: 2px; }
.sidebar-collapsible__inner .sidebar__item { padding-left: 34px; }

/* Collapsed: collapsible becomes icon-only */
.sidebar--collapsed .sidebar-collapsible__trigger { justify-content: center; padding: 0; width: 32px; height: 32px; margin: 0 auto; }
.sidebar--collapsed .sidebar-collapsible__label,
.sidebar--collapsed .sidebar-collapsible__chevron { display: none; }
.sidebar--collapsed .sidebar-collapsible__content { display: none; }

/* -------------------------------------------------------------------------
   Accordion Morph

   FAQ accordion donde la respuesta "se vierte" de la pildora como liquido
   (filtro goo). CSS es dueno del estado ESTATICO: pildora y panel pintan su
   propio fondo (por eso no hay twins "crisp" — ver accordion-morph.ts). El
   motion vive integro en packages/animations/src/accordion-morph.ts.

   La capa goo arranca invisible: solo el behavior la enciende. Sin JS (o con
   reduced-motion) el componente es un disclosure normal y completo.

   Colores: superficie = card + border (blanco en light, oscuro en dark — el
   bloque SIGUE al tema, decision Karen 2026-08-03; primary lo invertia).
   Jerarquia del texto via opacity tokens, no colores nuevos.

   Parts: .accordion-morph, __list, __row, __goo, __goo-pill, __goo-panel,
          __trigger, __index, __question, __icon, __panel, __panel-inner,
          __answer, __answer-line, __filter-svg
   ------------------------------------------------------------------------- */

/* Sin max-width propio: el ancho lo decide el layout que lo contenga
   (structure-only) — el 560px del original era el marco de su demo. */
.accordion-morph {
  position: relative;
  width: 100%;
}

.accordion-morph__filter-svg {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}

.accordion-morph__list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-morph__row {
  position: relative;
}

/* Capa filtrada: SOLO formas solidas — el filtro goo destruye el texto.
   Invisible hasta que el behavior la enciende (estado estatico sin halos). */
.accordion-morph__goo {
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0;
  pointer-events: none;
}

/* El liquido va en secondary, un paso mas oscuro que card y background en
   ambos temas: el cuello del vertido se lee como puente sutil, no invisible
   (card sobre background casi no contrasta) ni como mancha (primary gritaba). */
.accordion-morph__goo-pill,
.accordion-morph__goo-panel {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  background-color: #efefef;
  will-change: transform;
}

/* Radio constante — NUNCA se anima; el behavior lo aparca con inset detras
   de la capsula para que sus esquinas no asomen en reposo. */
.accordion-morph__goo-panel {
  border-radius: 16px;
}

/* La pildora pinta su propio fondo: elemento real y opaco ENCIMA del filtro,
   asi el wobble del blur queda tapado salvo en el cuello liquido. */
.accordion-morph__trigger {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 56px;
  padding: 16px 20px;
  background-color: #ffffff;
  border: 1px solid #e5e5e5;
  border-radius: 9999px;
  cursor: pointer;
  text-align: left;
  color: #0a0a0a;
  font-family: inherit;
  box-sizing: border-box;
}

.accordion-morph__trigger:hover {
  background-color: #f5f5f5;
}

.accordion-morph__trigger:focus-visible {
  outline: 2px solid var(--focus-ring-color);
  outline-offset: 2px;
}

.accordion-morph__index {
  flex-shrink: 0;
  min-width: 24px;
  font-size: 12.8px;
  font-weight: 500;
  color: #0a0a0a;
  opacity: 0.5;
}

.accordion-morph__question {
  flex: 1;
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.45;
  color: #0a0a0a;
}

.accordion-morph__icon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  color: #0a0a0a;
  opacity: 0.8;
  transform-origin: 50% 50%;
  will-change: transform;
}

.accordion-morph__panel {
  position: relative;
  z-index: 1;
  height: 0;
  overflow: hidden;
  will-change: height;
}

/* El panel tambien pinta su fondo (mismo rol crisp que la pildora). El
   margin-top ES el gap que el goo puentea — el behavior lo lee de
   --spacing-3 en runtime: cambiar el token mueve ambos a la vez. */
.accordion-morph__panel-inner {
  margin-top: 12px;
  padding: 20px;
  background-color: #ffffff;
  border: 1px solid #e5e5e5;
  border-radius: 16px;
}

.accordion-morph__answer {
  margin: 0;
  font-size: 12.8px;
  font-weight: 400;
  line-height: 1.45;
  letter-spacing: -0.02em;
  color: #0a0a0a;
  opacity: 0.8;
}

/* Mascara de linea para el reveal de SplitText: el clip vertical corta el
   texto que sube; el respiro em evita decapitar descendentes. */
.accordion-morph__answer-line {
  overflow-x: visible;
  overflow-y: clip;
  padding-bottom: 0.18em;
  margin-bottom: -0.18em;
}

@media (max-width: 767px) {
  .accordion-morph__trigger {
    padding: 12px 16px;
    gap: 12px;
  }

  .accordion-morph__panel-inner {
    padding: 16px;
  }
}

@media (max-width: 479px) {
  .accordion-morph__index {
    display: none;
  }
}
